create schema if not exists bronze;
create table if not exists bronze.customer_events(event_id uuid primary key,aggregate_id uuid not null,event_type text not null,payload jsonb not null,occurred_at timestamptz not null,ingested_at timestamptz not null default now());
create table if not exists bronze.domain_events(event_id uuid primary key,domain varchar(30) not null,event_type varchar(100) not null,payload jsonb not null,occurred_at timestamptz not null,ingested_at timestamptz not null default now());
